#!/usr/bin/env bash
# Re-author the figure panels at print width (review R03), then compose and audit.
#
# Why the discovery chain is excluded: 02/03/04/05 derive or consume the K=2 labels, and re-running the
# consensus clustering can move labels (mclapply shares one RNG stream), which would invalidate every
# downstream number. Their panels (plot_6..10) therefore keep their current authored size.
#
# Data discipline: every tracked data artefact regenerated by these scripts is restored to HEAD afterwards,
# so only the figures change. The scripts themselves are excluded from the restore.
set -uo pipefail
cd "$(dirname "$0")/.."
export CRC_PANEL_MAX_W="${CRC_PANEL_MAX_W:-3.4}"

scripts=(01_bulk_qc 17_proteomics_validation 19_methylation_analysis 20_spatial_analysis
         21_phospho_analysis 22b_dfs_validation 22d_dfs_replication 22e_gse38832_endpoints
         23_kinase_activity 24_spatial_niches 25_incremental_value 14_collect_plots)
for s in "${scripts[@]}"; do
  echo "=== ${s} ==="; date
  Rscript "06_Analysis/1_R/1_Rscripts/${s}.R" || echo "FAILED: ${s}"
done

echo "=== restoring regenerated data artefacts (figures kept) ==="
git checkout -- 05_QC 06_Analysis 07_Validation 08_Robustness 10_Tables 13_Reports Logs/DECISION_LOG.tsv \
  ':!06_Analysis/1_R/1_Rscripts'

echo "=== composing figures ==="
Rscript Scripts/compose_figures.R
echo "=== audits ==="
python3 Scripts/check_figure_citations.py | tail -2
python3 Scripts/audit_analysis.py | tail -1
echo "=== rerender complete ==="
